// Flag evaluation (server-side, streamed config - e.g. OpenFeature/LaunchDarkly-style)
public async Task<CheckoutResult> Checkout(CheckoutCommand cmd, CancellationToken ct)
{
    var useV2 = await _flags.IsEnabledAsync(
        key: "checkout-v2",
        user: UserTargeting.Of(cmd.UserId)      // stable hash per user
            .With("plan", cmd.Plan)
            .With("region", cmd.Region),
        defaultValue: false,                    // safe default: old path
        ct);

    return useV2
        ? await _checkoutV2.PlaceAsync(cmd, ct)
        : await _checkoutV1.PlaceAsync(cmd, ct);
}

// Rollout sequence:
//   day 0: flag off (deploy safety)
//   day 0: internal allowlist
//   day 1: 1% by stable user hash -> dashboards split by flag variant
//   day 3: 10% -> 50% -> 100%, each step gated on metrics
//   kill scenario: error rate spikes -> flag OFF globally, streamed in seconds,
//                  no redeploy, v1 path serves immediately
//   week 3: cleanup PR deletes the flag AND the v1 code path

// Frontend: risky logic stays server-side; client flags gate only UI variants,
// because you can't un-ship JavaScript from a user's cache.
